import json
from pathlib import Path

sources = json.loads(Path('source.json').read_text())
drafts = {}

def add(number, xml, reason, notes, removed=None, repeal=None, benefit=None):
    item = dict(proposed_xml=xml, reason=reason, review_notes=notes, status='rewrite_draft')
    if removed:
        item.update(change_type='normative_reduction', reform_policy_id='editorial_direction_2026_10_19', removed_provisions=removed)
    if repeal:
        item.update(change_type='full_repeal', repeal_policy_id='editorial_direction_2026_10_19', repeal_scope=repeal)
    if benefit:
        item['benefit_review'] = benefit
    drafts[number] = item

add('D4154-3', '''<p>En application du second alinéa de l'article L. 4154-1, l'employeur peut obtenir l'autorisation de confier les travaux mentionnés à l'article D. 4154-1 à des salariés temporaires ou à des salariés titulaires d'un contrat de travail à durée déterminée conclu avant l'entrée en vigueur de la loi instituant le contrat unique à durée indéterminée. Cette possibilité demeure ouverte aux salariés temporaires employés à durée indéterminée.</p>
<p>L'employeur adresse sa demande au directeur régional des entreprises, de la concurrence, de la consommation, du travail et de l'emploi par tout moyen conférant date certaine à sa réception. Il joint l'avis du comité social et économique et celui du médecin du travail. Il n'a pas à transmettre de nouvelle copie d'un avis exact, complet et à jour déjà légalement détenu par l'autorité destinataire ; celle-ci le réutilise pour l'instruction.</p>
<p>Ces modalités s'appliquent aux demandes adressées à compter de l'entrée en vigueur de la loi portant cette simplification. Pour l'application de l'article D. 4154-4 à ces demandes, le délai d'un mois court à compter de leur réception, quel que soit le moyen utilisé. Les demandes antérieures restent instruites sans nouveau dépôt et sans reprise de leur délai. Les autorisations déjà accordées conservent leurs effets dans les conditions de leur délivrance et de leur retrait. Le présent article ne permet ni la conclusion ni le renouvellement d'un contrat à durée déterminée après l'entrée en vigueur du contrat unique.</p>''',
    "Réforme de fond : suppression du recommandé postal exclusif et du renvoi d'avis déjà détenus, sans déclaration de remplacement. La dérogation favorable demeure accessible, y compris pour les futures missions de salariés temporaires en CDI. La rédaction conserve l'autorisation et les deux avis : les travaux visés exposent notamment à des agents cancérogènes ou aux rayonnements ionisants et justifient un contrôle préalable essentiel. Coordination prospective des anciens CDD avec le contrat unique.",
    "L4154-1, D4154-1 (ses 27 rubriques), D4154-4 et D4154-6 lus dans le corpus public. Le délai d'un mois de D4154-4 est expressément rattaché à la réception ; il faut reprendre son ancienne référence à la présentation du recommandé dans cet article hors lot. Enquête, prévention, formation, retrait et contrôles ne sont pas supprimés. La dénomination administrative ancienne de la source demeure à coordonner avec l'organisation actuelle des services. Le cadre européen de protection des travailleurs temporaires exposés aux travaux dangereux doit rester respecté ; aucune conformité générale n'est présumée.",
    removed=["Obligation d'adresser exclusivement la demande par lettre recommandée avec avis de réception.", "Obligation de joindre à nouveau les avis exacts et à jour déjà légalement détenus par le service instructeur."])

add('D4163-30-1', '''<p>Les dispositions suivantes s'appliquent aux demandes relatives à un projet de reconversion professionnelle :</p>
<p>1° Les articles R. 6323-10, R. 6323-10-1, R. 6323-10-2 et R. 6323-10-4, relatifs à la demande de congé. Toutefois, les délais d'anticipation de cent vingt jours et de soixante jours prévus au I de l'article R. 6323-10 ne sont pas opposables au demandeur. Le refus prévu au IV du même article ne peut être fondé ni sur ces délais ni sur l'ancienneté. Les autres mentions de la demande, le délai de réponse de trente jours, l'accord résultant du silence et les règles de report et de priorité demeurent applicables. Le justificatif d'assiduité demandé lors de la reprise du poste n'est pas exigé pour une période déjà régulièrement justifiée ;</p>
<p>2° L'article R. 6323-11, relatif à la compétence de la commission paritaire interprofessionnelle régionale ;</p>
<p>3° L'article R. 6323-12, relatif au positionnement préalable, seulement lorsque le projet comporte une action de formation mentionnée au 1° de l'article L. 6313-1, dans les conditions prévues à l'article D. 4163-30-3 ;</p>
<p>4° L'article R. 6323-13, relatif aux pièces à transmettre. Les pièces exactes, complètes et à jour déjà légalement accessibles à la commission sont réutilisées sans nouvelle production par le demandeur ;</p>
<p>5° Les articles R. 6323-11-1 et R. 6323-14-1, relatifs aux demandes des salariés titulaires d'un contrat à durée déterminée. Pour les contrats uniques à durée indéterminée conclus après l'entrée en vigueur de la loi les instituant, ces dispositions s'appliquent également : le salarié peut présenter sa demande pendant l'exécution du contrat et l'accord préalable de l'employeur est requis si la formation se déroule en tout ou partie sur son temps de travail. La formation peut débuter après la rupture effective du contrat, au plus tard six mois après celle-ci. Pendant le projet réalisé après cette rupture, le bénéficiaire a la qualité de stagiaire de la formation professionnelle ; il bénéficie de la rémunération et du maintien des régimes de sécurité sociale, d'assurance chômage et de retraite complémentaire prévus par l'article R. 6323-14-1. La commission verse aux régimes concernés les cotisations correspondant à ces garanties ;</p>
<p>6° L'article R. 6323-11-2, relatif aux demandes des salariés intermittents du spectacle, à l'exception de ses conditions d'ancienneté, qui ne s'appliquent pas au projet de reconversion professionnelle mentionné à l'article L. 4163-7 ;</p>
<p>7° L'article R. 6323-14-3, relatif aux dépenses prises en charge ;</p>
<p>8° Les articles R. 6323-15 et R. 6323-16, relatifs aux refus de prise en charge ;</p>
<p>9° Les articles D. 6323-18-1 à D. 6323-18-4, relatifs à la rémunération. Pour le projet réalisé après la rupture d'un contrat unique dans les conditions du 5°, la commission verse la rémunération conformément à l'article D. 6323-18-2. Pour ces nouveaux contrats, le salaire moyen de référence est calculé sur les douze mois précédant la formation ou, si cette base est plus favorable, selon le III de l'article D. 6323-18-3 en retenant les quatre derniers mois d'activité sous contrat unique. Pour cette seconde base, les exclusions des 1° à 4° du II de l'article D. 6323-9 restent applicables ; le 5° de ce II ne peut écarter une période au seul motif de la durée indéterminée du contrat. Ces bases ne se cumulent pas.</p>
<p>La fin d'une mission, d'une formation ou d'une période d'accompagnement n'est pas assimilée à la rupture du contrat unique. Les droits attachés aux contrats antérieurs restent applicables, sans autoriser de nouveau CDD ni son renouvellement. Les dispenses de délais et de nouvelle production de pièces prévues au présent article s'appliquent, dès l'entrée en vigueur de la loi portant cette simplification, aux demandes nouvelles et aux demandes en cours, sans nouveau dépôt, sans remise à zéro des délais déjà engagés et sans remise en cause des prises en charge accordées.</p>''',
    "Réforme de fond : retrait des anticipations impératives de 120 et 60 jours pour le congé de reconversion, du justificatif de retour déjà couvert et des pièces répétées accessibles à la commission. Le congé reste demandé et soumis aux règles de réponse, report et priorité : il ne devient pas une absence unilatérale. Les neuf rubriques sont conservées. Les prises en charge après CDD sont ouvertes au contrat unique après sa rupture effective, avec maintien de rémunération et de protection sociale ; le choix de la base salariale la plus favorable préserve l'utilité future de la référence de quatre mois sans cumul.",
    "Lecture des sources de tous les articles énumérés aux neuf rubriques, de D4163-30-3, L4163-7 et D6323-9. Restent notamment la gratuité du positionnement, le devis approuvé, les frais pédagogiques/annexes, cotisations, charges conventionnelles, refus motivés et recours. Les délais de 30 jours, reports de neuf mois, priorités, particularités des intérimaires et des intermittents restent régis par les renvois maintenus ; les délais de quatre/six mois de R6323-11-2 ne sont pas confondus avec les anticipations supprimées. Coordonner expressément R6323-11-1, R6323-14-1, D6323-18-2/3 et leurs références à D6323-9 pour le contrat unique, sans les déclarer réécrits dans ce lot. Les taux de rémunération et le plancher de D6323-18-4 ainsi que les avances aux petites entreprises ne sont pas réduits. La note du décret 2023-760 fixe l'entrée en vigueur historique au 1er septembre 2023 ; elle ne date pas la réforme proposée.",
    removed=["Délais d'anticipation obligatoires de cent vingt ou soixante jours pour la demande de congé de reconversion.", "Nouvelle justification à la reprise du poste pour les périodes d'assiduité déjà régulièrement justifiées.", "Nouvelle transmission des pièces exactes, complètes et à jour déjà légalement accessibles à la commission.", "Exclusion des futurs contrats uniques des facilités de prise en charge et de rémunération attachées aux demandes après CDD."])

add('R4451-58', '''<p>I.-L'employeur veille à ce que chaque travailleur relevant de l'une des situations suivantes reçoive une information appropriée :</p>
<p>1° Il accède à une zone délimitée en application des articles R. 4451-24 et R. 4451-28 ;</p>
<p>2° Il intervient dans une opération de transport de substances radioactives ;</p>
<p>3° Il est membre d'équipage à bord d'un aéronef ou d'un engin spatial ;</p>
<p>4° Il intervient dans une situation d'exposition durable résultant d'une urgence radiologique.</p>
<p>II.-Les travailleurs soumis à une surveillance dosimétrique individuelle au sens du I de l'article R. 4451-64 reçoivent une formation adaptée aux résultats de l'évaluation des risques réalisée conformément à la section 4 du présent chapitre.</p>
<p>III.-L'information et la formation portent notamment sur :</p>
<p>1° Les caractéristiques des rayonnements ionisants ;</p>
<p>2° Les effets de l'exposition sur la santé et, le cas échéant, l'incidence du tabagisme lors d'une exposition au radon ;</p>
<p>3° Les effets potentiellement néfastes de l'exposition sur l'embryon, en particulier au début de la grossesse, et sur l'enfant à naître, ainsi que la nécessité de déclarer la grossesse le plus tôt possible ;</p>
<p>4° Le nom et les coordonnées du conseiller en radioprotection ;</p>
<p>5° Les mesures prises en application du présent chapitre pour supprimer ou réduire les risques liés aux rayonnements ionisants ;</p>
<p>6° Les conditions d'accès aux zones délimitées au titre du présent chapitre ;</p>
<p>7° Les règles particulières applicables aux femmes enceintes ou qui allaitent, aux travailleurs de moins de dix-huit ans, aux titulaires d'un contrat de travail à durée déterminée conclu avant l'entrée en vigueur de la loi instituant le contrat unique à durée indéterminée et aux travailleurs temporaires, y compris lorsqu'ils sont employés à durée indéterminée ;</p>
<p>8° Les modalités de surveillance de l'exposition et d'accès aux résultats dosimétriques ;</p>
<p>9° La conduite à tenir en cas d'accident ou d'incident ;</p>
<p>10° Les règles particulières aux situations d'urgence radiologique ;</p>
<p>11° Le cas échéant, la sûreté des sources scellées de haute activité définies à l'annexe 13.7 visée à l'article R. 1333-1 du code de la santé publique et les conséquences possibles de la perte d'un contrôle adéquat de ces sources.</p>
<p>IV.-Lorsque le travailleur est exposé uniquement au radon, l'information ou la formation porte notamment sur :</p>
<p>1° L'origine naturelle du radon et sa transformation en particules solides radioactives ;</p>
<p>2° Les effets potentiels sur la santé et les interactions avec le tabagisme ;</p>
<p>3° Les moyens de prévenir l'exposition au radon ;</p>
<p>4° Les liens entre la concentration d'activité du radon dans l'air et la dose efficace pour le travailleur.</p>''',
    "Réécriture des quatre parties avec sujets et situations explicites ; conservation de chaque thème d'information et de formation. Coordination du 7° avec l'interdiction des nouveaux CDD, sans priver les intérimaires en CDI ni les anciens CDD des règles de protection applicables. Aucun allègement de fond des formations : elles préviennent un risque radiologique grave et ne constituent pas une simple formalité administrative.",
    "Contrôle des I à IV, des quatre situations du I, des onze thèmes du III et des quatre thèmes radon. Références R4451-24/28, R4451-64 I, section 4 et annexe 13.7 de R1333-1 CSP maintenues. Le seuil de dix-huit ans est inchangé. La prévention maternité et l'accès aux résultats ne sont pas supprimés. L'absence de nouveaux CDD ne dispense pas d'information pour les nouveaux contrats uniques. Le cadre Euratom de radioprotection appelle maintien et contrôle de concordance des prescriptions supérieures, sans prétendre les abroger.")

add('R4451-88', '''<p>En application du dernier alinéa de l'article L. 1251-22, l'entreprise utilisatrice définie au 1° de l'article L. 1251-1 assure, pour le salarié temporaire, le suivi individuel renforcé prévu à l'article R. 4451-82. Cette responsabilité s'applique également lorsque le salarié temporaire est employé à durée indéterminée.</p>
<p>Le médecin du travail de l'entreprise de travail temporaire est informé des résultats de ce suivi.</p>''',
    "Le responsable du suivi renforcé et le destinataire médical des résultats sont identifiés directement. La précision relative au CDI assure la continuité sous contrat unique ; elle ne crée pas un second examen. Maintien du dispositif pour sa fonction essentielle de prévention radiologique et de continuité médicale entre employeur et utilisateur.",
    "Dernier alinéa de L1251-22 lu : la charge du suivi renforcé appartient à l'entreprise utilisatrice, contrairement au suivi ordinaire à la charge de l'entreprise de travail temporaire. R4451-82 et L1251-1 1° restent les renvois de champ. La transmission est entre médecins ; elle n'autorise pas la remise du dossier médical à l'employeur. Aucun délai ou examen supplémentaire ajouté.")

add('R4451-100', '''<p>I.-Tout travailleur affecté au premier groupe mentionné au 1° du II de l'article R. 4451-99 :</p>
<p>1° Donne son accord à cette affectation ;</p>
<p>2° Ne présente pas de contre-indication médicale à une intervention en situation d'urgence radiologique ;</p>
<p>3° Reçoit une formation appropriée aux risques pour la santé et aux précautions à prendre lors d'une telle intervention. Cette formation est renouvelée au moins tous les trois ans.</p>
<p>Ne peuvent être affectés à ce groupe les travailleurs temporaires, y compris ceux employés à durée indéterminée, ainsi que les titulaires d'un contrat à durée déterminée ou d'un contrat conclu pour la durée d'un chantier avant l'entrée en vigueur de la loi instituant le contrat unique à durée indéterminée. Pour les relations de droit privé conclues après cette entrée en vigueur, la durée d'une mission ou d'un chantier ne peut fixer le terme de l'emploi.</p>
<p>II.-Tout travailleur affecté au second groupe mentionné au 2° du II de l'article R. 4451-99 :</p>
<p>1° Ne présente pas de contre-indication médicale à une intervention en situation d'urgence radiologique ;</p>
<p>2° Reçoit une information appropriée aux risques pour la santé et aux précautions à prendre lors de cette intervention.</p>''',
    "Réécriture des conditions propres à chacun des deux groupes, en conservant consentement, aptitude, contenu de formation et renouvellement triennal. Les références aux contrats à terme sont limitées aux contrats antérieurs ; l'exclusion du premier groupe reste applicable à tous les intérimaires, même en CDI. Aucune suppression de sécurité n'est justifiée dans l'intervention d'urgence radiologique.",
    "Les renvois aux 1° et 2° du II de R4451-99 et la périodicité minimale de trois ans sont conservés. La mention du chantier n'étend pas l'interdiction à tout salarié permanent intervenant matériellement sur un chantier. À coordonner avec D4154-1 23° et les autres règles du premier groupe ; la dérogation générale aux travaux dangereux ne vaut pas, par elle-même, effacement de cette interdiction spéciale. Les protections et le cadre Euratom restent distincts du préavis individuel de quinze jours.")

add('R4523-1', '''<p>La liste des postes de travail liés à la sécurité de l'installation, prévue à l'article L. 4523-2, précise, lorsqu'il y a lieu, au titre des actions de prévention prévues aux articles L. 4121-3 et L. 4121-4 :</p>
<p>1° Les postes qui ne peuvent être confiés à des salariés temporaires, y compris employés à durée indéterminée, ou à des salariés titulaires d'un contrat de travail à durée déterminée conclu avant l'entrée en vigueur de la loi instituant le contrat unique à durée indéterminée ;</p>
<p>2° Les postes destinés à être occupés par les salariés de l'établissement ;</p>
<p>3° Les postes dont les tâches nécessitent la présence d'au moins deux personnes qualifiées.</p>''',
    "Clarification de la liste et de ses trois catégories, avec coordination des anciens CDD et de l'intérim sous contrat unique. Les restrictions de sécurité sont conservées : elles identifient les postes critiques d'installations à risques majeurs et le besoin de deux intervenants qualifiés, sans ajouter de dépôt ou d'agrément.",
    "L4523-2 lu : la liste et la consultation du CSE ont une base autonome, de même que la consultation pour certaines sous-traitances. Renvois L4121-3/4 maintenus ; deux personnes qualifiées constituent un minimum inchangé. Ne pas confondre fin des nouveaux CDD et disparition de la catégorie des travailleurs temporaires. Aucune procédure collective ou autorisation de sécurité supprimée par le préavis individuel.")

add('R4543-22', '''<p>Tout travailleur qui effectue les interventions ou travaux mentionnés à l'article R. 4543-1 reçoit une formation particulière de l'entreprise qui l'emploie. Cette obligation concerne également les travailleurs temporaires, y compris employés à durée indéterminée, et les titulaires d'un contrat à durée déterminée conclu avant l'entrée en vigueur de la loi instituant le contrat unique à durée indéterminée. La formation est renouvelée aussi souvent que nécessaire, notamment lors de l'introduction de nouvelles technologies.</p>
<p>Elle porte notamment :</p>
<p>1° Sur l'évaluation du risque figurant dans l'étude de sécurité, afin de faciliter la compréhension et la mise en œuvre des mesures d'organisation et des mesures techniques qu'elle préconise ;</p>
<p>2° Sur les méthodes de travail et les procédures d'intervention applicables aux équipements sur lesquels le travailleur peut intervenir ;</p>
<p>3° Sur les équipements de travail et les équipements de protection individuelle à utiliser.</p>''',
    "Le débiteur de la formation et ses trois contenus sont formulés directement ; le renouvellement reste lié au besoin, sans périodicité administrative créée. La formation des interventions sur équipements élévateurs est maintenue en raison des risques graves de chute et d'écrasement. Les nouveaux contrats uniques et les anciens contrats conservent la même protection.",
    "Renvoi R4543-1, étude de sécurité, méthodes, procédures et équipements individuels maintenus. Aucune nouvelle attestation ou répétition à chaque mission n'est exigée. L'employeur reste responsable, y compris pour les intérimaires ; les obligations propres à l'entreprise utilisatrice ne sont pas implicitement transférées. Les trois numéros sont conservés.")

add('D4622-31', '''<p>Le comité interentreprises ou la commission de contrôle est consulté sur l'organisation et le fonctionnement du service de prévention et de santé au travail, notamment sur :</p>
<p>1° Le budget du service et son exécution ;</p>
<p>2° La modification de sa compétence géographique ou professionnelle ;</p>
<p>3° La création, la suppression ou la modification de secteurs ;</p>
<p>4° La création ou la suppression d'un emploi de médecin du travail, d'intervenant en prévention des risques professionnels ou d'infirmier ;</p>
<p>5° Abrogé ;</p>
<p>6° La nomination, le changement d'affectation, le licenciement, la rupture conventionnelle du contrat de travail et le transfert d'un médecin du travail, ainsi que la rupture de son contrat à durée déterminée conclu avant l'entrée en vigueur de la loi instituant le contrat unique à durée indéterminée, dans les cas prévus à l'article L. 4623-5-1 ;</p>
<p>7° Le licenciement d'un intervenant en prévention des risques professionnels ou d'un infirmier.</p>
<p>Le comité ou la commission peut aussi être consulté sur toute question relevant de sa compétence.</p>
<p>La suppression de la consultation distincte du 5° s'applique aux consultations qui n'ont pas encore eu lieu à la date d'entrée en vigueur de la loi portant cette suppression. Elle ne dispense ni de la consultation prévue au 6° ni de l'accord requis pour la nomination et l'affectation par l'article R. 4623-5. Les consultations déjà intervenues restent valables. Aucun nouveau contrat à durée déterminée ni renouvellement ne peut être fondé sur le présent article après l'entrée en vigueur du contrat unique.</p>''',
    "Réforme de fond : suppression de la consultation supplémentaire propre au recrutement en CDD, qui double le contrôle de nomination et d'affectation maintenu au 6° et à R4623-5. Les six autres rubriques, la compétence générale et les garanties d'indépendance restent entières. Les ruptures des anciens CDD continuent d'être contrôlées.",
    "Le numéro 5° est conservé comme abrogé afin de ne pas décaler les renvois. R4623-5 et L4623-5-1 lus ; les accords de nomination et autorisations de rupture sont distincts et non supprimés. La mesure ne transforme pas le préavis de quinze jours en procédure complète de licenciement d'un médecin protégé. La faculté de consultation générale ne reconstitue pas une consultation obligatoire distincte sur le seul recrutement sous l'ancien type de contrat.",
    removed=["Consultation obligatoire distincte sur le seul recrutement d'un médecin du travail en contrat à durée déterminée, en doublon de sa nomination."])

add('R4623-8', '''<p>Les instances mentionnées à l'article R. 4623-5 sont consultées avant la fin de la période d'essai, au plus tard.</p>
<p>Si l'accord de ces instances n'est pas obtenu, la nomination du médecin du travail est subordonnée à l'autorisation de l'inspecteur du travail, qui se prononce après avis du médecin inspecteur du travail.</p>''',
    "Réécriture à droit constant du moment de la consultation et de la voie permettant la nomination en l'absence d'accord. La solution administrative favorable reste ouverte ; l'autorisation n'est pas supprimée, car elle arbitre un désaccord intéressant l'indépendance du médecin du travail. Aucun dépôt ni délai minimal supplémentaire n'est introduit.",
    "R4623-5 lu : CSE ou comité interentreprises/commission de contrôle, et conseil d'administration dans les conditions de cet article. Le texte ne vaut pas autorisation tacite et ne prolonge pas l'essai. Pour les nouveaux contrats, coordonner L1221-19 et suivants sur l'essai de trois mois sans renouvellement ; les essais antérieurs restent protégés. Les notes de 2009/2010 concernent des entrées en vigueur territoriales historiques, non une date future. La nomination et la rupture relèvent de procédures différentes.")

add('R4623-18', '''<p>Lorsque le licenciement ou la rupture conventionnelle du contrat de travail d'un médecin du travail est envisagé, les instances compétentes se prononcent après l'avoir entendu : le comité social et économique, le comité interentreprises ou la commission de contrôle, ainsi que le conseil d'administration, selon le cas. Il en va de même pour la rupture d'un contrat à durée déterminée conclu avant l'entrée en vigueur de la loi instituant le contrat unique à durée indéterminée, dans les cas prévus à l'article L. 4623-5-1. L'entretien préalable prévu à l'article L. 1232-2 a lieu avant la consultation de l'instance.</p>''',
    "Le sujet des consultations et l'ordre entretien/audition/avis sont explicités. Coordination des seuls CDD antérieurs avec la réforme de l'emploi. Les consultations, la défense du médecin et les compétences propres de chaque instance sont maintenues, car elles protègent son indépendance et ne sont pas absorbées par le préavis individuel.",
    "L4623-4, L4623-5 et L4623-5-1 lus, ainsi que R4623-19 à R4623-22 : le vote secret, les règles de représentation, l'enquête contradictoire et l'autorisation de l'inspecteur restent distincts. Le renvoi à L1232-2 est conservé, sans prétendre qu'il vise toute rupture conventionnelle. Les consultations sont celles requises selon le cas ; aucune instance supplémentaire n'est créée. L'ancien CDD ne peut être renouvelé après la réforme par cet article.")

add('R4623-20', '''<p>L'employeur adresse à l'inspecteur du travail dont dépend le service de prévention et de santé au travail qui emploie le médecin, par tout moyen conférant date certaine à sa réception, la demande d'autorisation de licenciement. Il lui adresse dans les mêmes conditions, pour les contrats à durée déterminée conclus avant l'entrée en vigueur de la loi instituant le contrat unique à durée indéterminée, la demande d'autorisation de rupture dans les cas prévus à l'article L. 4623-5-1 et la demande de constatation de l'arrivée du terme prévue à l'article L. 4623-5-2.</p>
<p>En cas de licenciement, de rupture anticipée ou de non-renouvellement d'un ancien contrat à durée déterminée, la demande expose les motifs de la mesure envisagée. Le procès-verbal de la réunion des instances mentionnées à l'article R. 4623-18 y est joint, sauf s'il est déjà légalement détenu, dans sa version complète et exacte, par l'inspecteur saisi ; dans ce cas, il est réutilisé sans nouvelle copie.</p>
<p>La demande est transmise dans les quinze jours suivant la délibération des instances mentionnées à l'article R. 4623-18, sous réserve du délai de quarante-huit heures applicable en cas de mise à pied.</p>
<p>En cas de mise à pied, ces instances sont consultées dans les dix jours à compter de celle-ci.</p>
<p>Dans ce cas, la demande d'autorisation de licenciement, de rupture de l'ancien contrat à durée déterminée avant son terme ou de non-renouvellement est transmise à l'inspecteur du travail dans les quarante-huit heures suivant la délibération de ces instances.</p>
<p>La dispense de nouvelle copie du procès-verbal s'applique aux demandes nouvelles et en cours à compter de l'entrée en vigueur de la loi portant cette simplification, sans nouveau dépôt et sans reprise des délais. Elle ne supprime pas la consultation, la motivation ni l'autorisation ou la constatation requise. Les règles applicables aux anciens contrats demeurent opposables à leur arrivée au terme, sans autoriser de nouveau CDD ni son renouvellement après l'entrée en vigueur du contrat unique. Le préavis individuel ne dispense pas de la procédure de protection et n'autorise pas la rupture avant la décision requise.</p>''',
    "Réforme de fond ciblée : suppression de la nouvelle copie d'un procès-verbal déjà légalement détenu par l'inspecteur, tout en maintenant consultation, motivation et contrôle préalable. Les anciens CDD conservent leurs autorisations et constatations. La rédaction explicite le rapport entre les quinze jours ordinaires et les quarante-huit heures de la séquence de mise à pied, au lieu de laisser les deux délais apparemment concurrents.",
    "R4623-18 à R4623-22 et L4623-5-1/5-2 lus. Chiffres conservés : quinze jours pour transmettre, dix jours pour consulter après mise à pied, quarante-huit heures pour la transmission urgente. Incohérence rédactionnelle préexistante signalée : le dernier alinéa source ne répète pas expressément la condition de mise à pied de l'alinéa précédent ; le projet retient explicitement son rattachement à cette procédure urgente, point à confronter à l'historique réglementaire avant adoption. L4623-5-2 impose par ailleurs une saisine un mois avant le terme : cette règle spéciale n'est pas supprimée par le délai suivant la consultation. Les délais d'enquête de R4623-21 restent distincts. La réutilisation du procès-verbal ne retarde pas l'instruction.",
    removed=["Obligation de joindre une nouvelle copie du procès-verbal complet et exact déjà légalement détenu par l'inspecteur saisi."])

add('R4623-25-4', '''<p>Le candidat à l'autorisation d'exercice est lié par un contrat de travail à l'employeur ou au président du service de prévention et de santé au travail interentreprises. Pour un recrutement de droit privé intervenant après l'entrée en vigueur de la loi instituant le contrat unique, ce contrat est à durée indéterminée.</p>
<p>Pour ces nouveaux contrats, les fonctions sont exercées dans les conditions du second alinéa du I de l'article R. 4623-25-3. Lorsqu'un stage est prescrit en application de l'article R. 4111-17 du code de la santé publique, la période d'accomplissement de ce stage au titre du présent article correspond à sa durée prescrite, dans la limite de trois ans. La fin des fonctions requises ou du stage ne met pas automatiquement fin à l'emploi et ne dispense pas de l'autorisation nécessaire à l'exercice de la médecine.</p>
<p>La rupture individuelle du nouveau contrat de droit privé intervient avec un préavis de quinze jours calendaires à compter de sa notification, à l'initiative de l'employeur comme du salarié, sous réserve des dispenses favorables ouvertes au salarié. Le motif patronal doit être valable et contrôlable ; les garanties de défense, de non-discrimination et de santé, les protections liées à la maternité et à la représentation, les autorisations spéciales et les recours demeurent applicables. Les procédures collectives et leurs délais restent distincts. L'indemnité ordinaire est due uniquement en cas de rupture par l'employeur : aucune avant un an d'ancienneté ; à partir d'un an, 0,20 mois de salaire de référence, déterminé selon l'article R. 1234-4, par année totale d'ancienneté, fractions d'année au prorata, dans la limite de six mois de ce salaire. Le seuil est apprécié au terme effectif du contrat, préavis inclus ; la première année n'est pas retranchée une fois ce seuil atteint. Les salaires, congés acquis et réparations d'une illégalité restent dus selon leur régime propre. Les indemnités spéciales conservent leur régime, notamment, pour l'inaptitude d'origine professionnelle, le doublement, le salaire de référence et l'absence de seuil d'ancienneté qui leur sont propres ; le seuil d'un an et le plafond de l'indemnité ordinaire ne les limitent pas.</p>
<p>Pour les contrats conclus avant cette entrée en vigueur et pour les contrats de droit public qui ne relèvent pas du contrat unique, la durée du contrat reste, selon le cas, conforme au second alinéa du I de l'article R. 4623-25-3 ou égale à la durée du stage prescrit en application de l'article R. 4111-17 du code de la santé publique, dans la limite de trois ans. Le non-renouvellement à l'issue d'une période d'engagement est notifié avec un préavis de deux mois ; les démissions sont présentées avec le même préavis. Les contrats antérieurs conservent leur ancienneté, leurs créances et leurs droits acquis ; aucune même période ne donne lieu à une double indemnisation. Une conversion convenue en contrat unique conserve toute l'ancienneté et les créances acquises. Ces dispositions ne permettent ni de conclure un nouveau CDD de droit privé ni d'en renouveler un après l'entrée en vigueur de la réforme.</p>''',
    "Réforme de fond : le stage et les fonctions préparant l'autorisation ne fixent plus le terme du nouvel emploi de droit privé. Le préavis spécial de deux mois est remplacé, pour le nouveau contrat uniquement, par les quinze jours calendaires et le barème ordinaire décidé par l'auteur. La phase pédagogique conserve ses conditions propres et la limite de trois ans du stage. La durée, les préavis et les droits des anciens contrats et des agents publics restent expressément distingués.",
    "R4623-25-3 lu intégralement. Incohérence préexistante : son I, second alinéa, règle l'exercice à temps plein ou partiel, sans définir une durée de contrat ; le renvoi ne peut fournir un terme chiffré. Le projet conserve le renvoi et distingue explicitement quotité des fonctions, stage et emploi, sans inventer une durée manquante. R4111-17 CSP n'est pas fourni dans ce corpus et sa concordance avec les références R4111-18 de R4623-25-3 doit être vérifiée ; aucune réécriture du CSP n'est affirmée. Autorisation d'exercice, motifs légaux, éventuel statut protecteur et procédures collectives demeurent. Coordonner le modèle contractuel extérieur et L1234-9/R1234-1/2/4 pour le barème, sans appliquer le zéro de première année aux indemnités spéciales ni effacer la composante acquise des anciens contrats.",
    removed=["Fixation du terme des nouveaux emplois de droit privé par la durée des fonctions préparatoires ou du stage d'autorisation d'exercice.", "Préavis spécial de deux mois pour les démissions relevant des nouveaux contrats uniques de droit privé.", "Possibilité de terminer automatiquement un nouvel emploi de droit privé par non-renouvellement d'une période d'engagement."])

add('R4625-1', '''<p>Les chapitres Ier à IV s'appliquent aux travailleurs titulaires d'un contrat à durée déterminée conclu avant l'entrée en vigueur de la loi instituant le contrat unique à durée indéterminée. La périodicité de leur suivi individuel de santé est équivalente à celle des salariés employés à durée indéterminée ; ils bénéficient notamment des dispositions des articles R. 4624-15 et R. 4624-27.</p>
<p>Les travailleurs recrutés sous contrat unique relèvent des mêmes chapitres et conservent, lorsque leurs conditions sont remplies, les dispenses de nouvelle visite ou de nouvel examen prévues aux articles R. 4624-15 et R. 4624-27. Une conversion convenue d'un ancien contrat en contrat unique ne suffit pas, à elle seule, à rendre ces dispenses inapplicables.</p>''',
    "Réécriture de la garantie de suivi des anciens CDD et coordination des nouveaux emplois à durée indéterminée. Maintien explicite des dispenses de visites redondantes pour les situations futures éligibles ; la seule conversion contractuelle ne doit pas les fermer. La périodicité protectrice n'est pas réduite et aucune nouvelle visite de conversion n'est créée.",
    "R4624-15 et R4624-27 lus : leurs conditions cumulatives restent entières, notamment emploi identique, risques équivalents, détention de l'attestation ou de l'avis et absence de mesure ou d'inaptitude sur les périodes de cinq/trois ans et deux ans respectivement. Ces dispenses n'effacent pas le suivi périodique ou les nouveaux risques. La catégorie historique CDD ne fonde aucune nouvelle embauche à terme ; les règles propres aux agents publics ne sont pas modifiées.")

add('R4626-12', '''<p>L'établissement informe le comité technique d'établissement et le comité social et économique de la nomination ou du recrutement du médecin du travail.</p>
<p>Sans préjudice des règles disciplinaires applicables aux personnels visés à l'article L. 952-21 du code de l'éducation et au 1° de l'article L. 6152-1 du code de la santé publique, la décision de licencier le médecin du travail ou de rompre ou de ne pas renouveler son contrat à durée déterminée est subordonnée à l'avis conforme de l'inspecteur du travail. Celui-ci rend son avis après consultation du comité social et économique compétent et avis du médecin inspecteur du travail.</p>
<p>À compter de l'entrée en vigueur de la loi portant cette simplification, l'information distincte du directeur régional des entreprises, de la concurrence, de la consommation, du travail et de l'emploi sur la nomination ou le recrutement n'est plus requise, y compris pour les informations non encore transmises à cette date. Les informations déjà données restent valables. Cette suppression ne dispense d'aucune consultation ni d'aucun avis requis pour protéger l'indépendance du médecin.</p>
<p>Pour les relations de droit privé relevant de la loi instituant le contrat unique, les dispositions relatives à la rupture et au non-renouvellement d'un contrat à durée déterminée ne concernent que les contrats conclus avant son entrée en vigueur ; elles n'autorisent ni nouveau CDD ni renouvellement. Les contrats relevant du droit public conservent leur régime. Le préavis individuel du contrat unique ne remplace pas l'avis conforme ni les procédures distinctes applicables.</p>''',
    "Réforme de fond : suppression de la notification administrative distincte de la nomination ou du recrutement au directeur régional, sans déclaration de remplacement. Les représentants compétents restent informés ; les avis et le contrôle de rupture, nécessaires à l'indépendance médicale, sont maintenus. La transition distingue les anciens CDD privés et le droit public.",
    "R4626-9 à R4626-11 lus : qualification, ancienne dérogation de diplôme au 8 septembre 1985 et modèle contractuel ont des bases autonomes non supprimées. Les références L952-21 éducation et L6152-1 1° CSP sont maintenues, sans prétendre réécrire ces codes non fournis. Les dénominations comité technique d'établissement/CSE sont celles de la source ; leur actualisation aux instances hospitalières doit être coordonnée explicitement selon les établissements, sans supprimer une représentation par inférence. L'avis est conforme, non simplement consultatif. La suppression de l'information au directeur régional ne vaut pas suppression d'une autorisation spéciale.",
    removed=["Information distincte obligatoire du directeur régional sur chaque nomination ou recrutement d'un médecin du travail dans l'établissement."])

add('R5122-18', '''<p>L'employeur verse au salarié placé en activité partielle une indemnité horaire égale à 60 % de sa rémunération brute servant d'assiette à l'indemnité de congés payés prévue au II de l'article L. 3141-24. Cette rémunération est ramenée à un montant horaire sur la base de la durée légale du travail applicable dans l'entreprise ou, si elle est inférieure, de la durée collective du travail ou de la durée stipulée au contrat. La durée légale retenue est celle applicable au salarié concerné : le passage du seuil hebdomadaire à quarante heures pour les nouveaux contrats ne relève pas celui des contrats antérieurs, fixé à trente-cinq heures, et ne réduit pas le salaire contractuel.</p>
<p>La rémunération retenue pour calculer cette indemnité horaire est plafonnée à 4,5 fois le taux horaire du salaire minimum interprofessionnel de croissance.<br />Pour les éléments de rémunération variables ou versés selon une périodicité autre que mensuelle, le salaire de référence servant au calcul de l'indemnité et de l'allocation d'activité partielle comprend la moyenne des éléments perçus au cours des douze mois civils précédant le premier jour de placement de l'entreprise en activité partielle. Si le salarié a travaillé moins de douze mois civils, la moyenne porte sur la totalité des mois travaillés au cours de cette période.</p>
<p>Pendant les actions de formation mentionnées à l'article L. 5122-2 réalisées durant les heures chômées, l'indemnité horaire est portée à 100 % de la rémunération nette antérieure du salarié.</p>
<p>Pour les salariés en contrat d'apprentissage ou de professionnalisation, l'allocation mentionnée à l'article L. 5122-1 ne peut dépasser le montant de l'indemnité horaire due par l'employeur.</p>
<p>L'indemnité nette versée par l'employeur ne peut dépasser la rémunération nette horaire habituelle du salarié. L'indemnité et la rémunération nettes sont calculées après déduction des cotisations et contributions obligatoires retenues par l'employeur.</p>
<p>Pour tous les salariés des entreprises de travail temporaire régis par le chapitre Ier du titre V du livre II de la première partie du présent code, y compris ceux mentionnés à l'article L. 1251-58-1, et pour les salariés mentionnés à l'article L. 3123-1, le taux horaire de l'indemnité d'activité partielle ne peut être inférieur au taux horaire du salaire minimum interprofessionnel de croissance, sous réserve du dernier alinéa. L'inclusion des salariés mentionnés à l'article L. 1251-58-1 dans cette garantie s'applique aux heures chômées à compter de l'entrée en vigueur de la loi portant cette extension, y compris sous un contrat déjà en cours. Les heures antérieures restent régies par les règles qui leur étaient applicables. Le contrat unique ne supprime ni les droits liés à l'apprentissage et à la professionnalisation ni la garantie mensuelle et le décompte des intermissions propres au CDI intérimaire.</p>
<p>Lorsque le taux horaire de rémunération d'un salarié mentionné à l'alinéa précédent est inférieur au taux horaire du salaire minimum interprofessionnel de croissance, son indemnité horaire d'activité partielle est égale à son taux horaire de rémunération.</p>''',
    "Réforme favorable : suppression de l'exclusion des intérimaires déjà en CDI du plancher horaire d'indemnisation. Elle évite que le passage obligatoire au contrat unique ferme ce plancher aux situations futures. Les taux de 60 % et 100 %, le plafond de 4,5 SMIC, les références de douze mois et les plafonds nets sont maintenus. La rédaction distingue les durées légales selon la transition décidée, sans rehausser les régimes annuels par renvoi.",
    "L1251-58-1 lu : les missions successives sont distinctes du contrat d'emploi. L'extension est expresse, y compris aux CDI intérimaires antérieurs pour les heures futures ; elle ne crée pas de double indemnisation des intermissions. La réserve du dernier alinéa maintient l'indemnité au salaire horaire effectivement inférieur au SMIC. Les limites apprentissage/professionnalisation et formation restent distinctes. Coordonner L3121-27 à 29 sans relever automatiquement L3121-41/44, L3123-1 ou 1 607 heures. Note source : application historique aux heures chômées depuis le 1er janvier 2023, non date de la nouvelle extension. Aucun financement ni rendement chiffré n'est présumé.",
    removed=["Exclusion des salariés intérimaires mentionnés à L1251-58-1 du plancher horaire favorable d'indemnisation de l'activité partielle."])

add('R5131-21', '''<p>Pour l'application du 1° de l'article R. 5131-20, les ressources suivantes sont déduites intégralement du montant forfaitaire de l'allocation :</p>
<p>1° Les allocations versées aux travailleurs privés d'emploi en application du titre II du livre IV de la cinquième partie du présent code ou de l'article L. 1233-68 ;</p>
<p>2° Les revenus tirés des stages de formation professionnelle ;</p>
<p>3° La rémunération perçue au titre d'un parcours de formation dispensé par une école de la deuxième chance mentionnée à l'article L. 214-14 du code de l'éducation.</p>''',
    "Réécriture à droit constant de la liste exhaustive des ressources intégralement imputées sur l'allocation du contrat d'engagement jeune. La déduction est rattachée explicitement au montant de cette allocation pour éviter de la présenter comme un avantage fiscal. La coordination des prestations de remplacement et de formation conserve ici sa fonction de calcul sous condition de ressources ; l'article ne crée aucune déclaration ou pièce autonome susceptible d'être supprimée.",
    "R5131-20, R5131-22, D5131-23, R5131-24 et L5131-6 lus pour vérifier le sens de l'imputation. Les trois catégories et leurs références sont maintenues. Les ressources non visées continuent de relever de leur régime de cumul ; aucune extension de la liste par analogie aux salaires sous contrat unique. La note du décret 2022-199 renvoie au 1er mars 2022, date historique. Les modalités justificatives de R5131-25, distinctes et hors lot, ne sont pas déclarées supprimées.",
    benefit="La déduction intégrale de ces trois ressources n'est pas une déduction fiscale favorable : elle diminue l'allocation CEJ. Les allocations chômage et de sécurisation professionnelle, les revenus de stage et la rémunération des écoles de la deuxième chance restent dus selon leurs fondements propres ; aucun de ces droits n'est abrogé. Le droit à l'allocation CEJ, son incessibilité, son insaisissabilité et ses exonérations fiscales et sociales prévues à L5131-6 demeurent ouverts aux futures personnes éligibles. Les cumuls intégraux ou partiels de R5131-20 et R5131-22 et les exceptions favorables de R5131-24 ne sont ni supprimés ni restreints par cette liste, qui n'est pas étendue.")

add('R5131-24', '''<p>I.-L'allocation mentionnée à l'article L. 5131-6 ne se cumule pas avec le revenu de solidarité active mentionné à l'article L. 262-1 du code de l'action sociale et des familles, sauf pour les personnes à charge mentionnées à l'article R. 262-3 du même code. Les bénéficiaires du revenu de solidarité active, ainsi que leur conjoint, concubin ou partenaire lié par un pacte civil de solidarité, qui ont conclu un contrat d'engagement jeune dans le cadre de l'article R. 5131-6 ne bénéficient pas de l'allocation prévue à l'article L. 5131-6.</p>
<p>II.-L'allocation mentionnée à l'article L. 5131-6 ne se cumule pas avec la prime d'activité mentionnée à l'article L. 841-1 du code de la sécurité sociale, sauf pour les personnes à charge mentionnées à l'article R. 842-3 du même code. Toutefois, si le droit à la prime est ouvert au titre d'une activité antérieure au premier mois de bénéfice de l'allocation, la prime correspondant à cette période d'activité reste cumulable avec l'allocation. Le versement de l'allocation prend fin, le cas échéant, à compter de l'ouverture du droit à la prime d'activité.</p>
<p>III.-Les rémunérations, allocations et indemnités suivantes ne se cumulent pas avec l'allocation mentionnée à l'article L. 5131-6. Le cas échéant, le versement de l'allocation est suspendu pendant la période au cours de laquelle le jeune les perçoit :</p>
<p>1° La rémunération du volontariat dans les armées mentionné à l'article L. 4132-11 du code de la défense ;</p>
<p>2° La rémunération du service militaire volontaire visé à l'article 32 de la loi n° 2018-607 du 13 juillet 2018 relative à la programmation militaire pour les années 2019 à 2025 et portant diverses dispositions intéressant la défense ;</p>
<p>3° La rémunération du service militaire adapté mentionné à l'article 17 du décret n° 2008-955 du 12 septembre 2008 relatif aux volontariats militaires ;</p>
<p>4° L'indemnité du service civique mentionnée aux articles R. 121-23 et R. 121-24 du code du service national ;</p>
<p>5° L'allocation prévue par le décret n° 2005-888 du 2 août 2005 relatif à l'allocation versée aux volontaires pour l'insertion et à la prime versée aux volontaires pour l'insertion et aux volontaires pour un contrat de service en établissement public d'insertion de la défense ;</p>
<p>6° Abrogé.</p>
<p>À compter de l'entrée en vigueur de la loi portant cette suppression, les rémunérations des emplois d'insertion relevant des articles L. 5132-5, L. 5132-11-1, L. 5132-15-1 ou L. 5132-6 et du contrat unique d'insertion mentionné à l'article L. 5134-19-3 relèvent du régime des revenus d'activité salariée prévu au 1° de l'article R. 5131-22 et au 2° du I de l'article R. 5131-20. Elles ne justifient plus, à elles seules, la suspension automatique de l'allocation, que l'emploi relève d'un ancien contrat ou du nouveau contrat unique à durée indéterminée. Les ressources des périodes antérieures restent traitées selon les règles qui leur étaient applicables, sans remboursement rétroactif général. Les autres conditions de l'allocation et les exceptions de cumul prévues aux I et II demeurent applicables.</p>''',
    "Réforme de fond favorable : suppression du non-cumul automatique propre aux salaires des emplois d'insertion et des CUI. Ces salaires suivent désormais la dégressivité ordinaire des revenus d'activité, avec ses paramètres existants, pour les contrats anciens comme futurs. Les règles RSA, prime d'activité et volontariats conservent leur objet de coordination de prestations et toutes leurs exceptions ; aucune nouvelle catégorie de revenu n'est exclue.",
    "R5131-20, R5131-22, D5131-23 et L5131-6 lus : le 6° supprimé ne devient pas un cumul intégral sans condition ; les revenus sont partiellement déductibles selon le seuil et le coefficient existants, sans nouveau taux. Les exceptions personnes à charge, prime pour activité antérieure et les cinq prestations du III sont conservées. Les années 2019 à 2025 désignent la loi citée, pas une échéance nouvelle du dispositif. Coordonner les circuits de versement et R5131-25 pour éviter une suspension encore fondée sur l'ancien 6°, sans prétendre ces articles réécrits. L'extension n'impose ni maintien fictif du CEJ après sa fin ni nouveau CDD.",
    removed=["Non-cumul automatique de l'allocation CEJ et suspension de son versement du seul fait de la perception d'un salaire d'emploi d'insertion ou de CUI."])

add('R5132-7', '''<p>L'embauche, par une entreprise d'insertion, d'une personne mentionnée à l'article L. 5132-1 dans le cadre du contrat unique à durée indéterminée ouvre droit à une aide financière, dans la limite du nombre de postes d'insertion fixé par la convention. Il en va de même de l'emploi, par cette entreprise, d'une personne détenue ayant signé un contrat d'emploi pénitentiaire. Les embauches en contrat à durée déterminée intervenues avant l'entrée en vigueur de la loi instituant le contrat unique conservent le bénéfice de l'aide dans les conditions qui leur sont applicables.</p>
<p>L'aide comprend un montant socle et un montant modulé. Le préfet détermine chaque année le montant modulé, dans les conditions prévues à l'article R. 5132-8, en tenant compte :</p>
<p>- des caractéristiques des personnes embauchées et, le cas échéant, des personnes détenues ayant signé un contrat d'emploi pénitentiaire ;</p>
<p>- des actions et des moyens d'insertion mis en œuvre ;</p>
<p>- des résultats constatés à la sortie de la structure.</p>
<p>Pour les embauches intervenant à compter de l'entrée en vigueur de la loi instituant le contrat unique, la durée indéterminée de l'emploi ne peut, à elle seule, exclure l'aide ou en réduire le montant. La durée du parcours, de la convention ou de l'aide ne fixe pas le terme de l'emploi. Les conventions en cours et les droits déjà constitués restent applicables ; aucun nouveau conventionnement n'est exigé du seul fait de la substitution du contrat unique au CDD. Le présent article ne permet ni nouveau CDD ni renouvellement après cette entrée en vigueur.</p>''',
    "Réforme de fond : retrait de l'obligation d'embaucher en CDD pour accéder à l'aide au poste d'insertion, remplacée par l'éligibilité du contrat unique sans terme d'emploi. Le socle, la modulation annuelle, les trois critères, le contingent de postes et la branche pénitentiaire sont maintenus. Les futurs emplois éligibles conservent l'aide sans nouvelle convention due au seul changement de forme contractuelle.",
    "L5132-2, L5132-3, L5132-5 et R5132-8 lus. L'aide reste soumise à l'éligibilité du parcours et aux postes conventionnés ; elle n'est pas promise indéfiniment pour toute la durée du CDI. Coordonner L5132-5 et les arrêtés de montant/versement, sans rétablir terme, renouvellement de CDD ou fin automatique d'emploi. Le contrat pénitentiaire constitue un régime distinct et n'est pas converti par cette disposition. La note source renvoie aux V et VI de l'article 2 du décret 2021-1128 : leurs règles d'application antérieures restent réservées pour les droits concernés. Aucun montant nouveau ni économie budgétaire inventé.",
    removed=["Condition de recrutement sous contrat à durée déterminée pour ouvrir l'aide financière aux futurs salariés éligibles des entreprises d'insertion."])

add('R5132-8', '''<p>L'entreprise d'insertion reçoit l'aide financière pour chaque poste de travail occupé à temps plein. Lorsque l'occupation du poste est inférieure à un temps plein, le montant de l'aide est réduit à due proportion.</p>
<p>Un arrêté conjoint des ministres chargés de l'emploi et du budget fixe le montant socle, le montant maximal de la part modulée dans la limite d'un pourcentage du montant socle, ainsi que les conditions de versement de l'aide, respectivement pour les salariés en insertion recrutés sous contrat unique à durée indéterminée et pour les personnes détenues ayant signé un contrat d'emploi pénitentiaire. Les dispositions applicables aux salariés en insertion sous CDD restent applicables aux contrats conclus avant l'entrée en vigueur de la loi instituant le contrat unique et s'appliquent aux nouveaux contrats uniques de même objet, sans exclusion ni réduction tenant à leur durée indéterminée. Depuis le 1er janvier 2015, un arrêté conjoint de ces ministres revalorise chaque année l'aide en fonction de l'évolution du salaire minimum de croissance.</p>
<p>La substitution du contrat unique au CDD s'applique aux embauches de droit privé intervenant à compter de l'entrée en vigueur de la loi l'instituant. Elle n'interrompt ni les versements ni la revalorisation en l'absence de modification des arrêtés ou conventions existants. Les droits antérieurs restent applicables. La durée de versement de l'aide ne fixe pas le terme du contrat de travail.</p>''',
    "Réécriture du prorata, des compétences ministérielles et de la revalorisation annuelle. Réforme de fond coordonnée : suppression de la restriction de la branche salariale aux CDD, afin de préserver ses montants et modalités pour les futurs contrats uniques sans attendre de nouveaux arrêtés. Le régime distinct des personnes détenues demeure et aucune aide ni revalorisation n'est supprimée.",
    "Concordance avec R5132-7 rédigé dans le lot ; maintien temps plein/prorata, socle, maximum de part modulée lié au socle et arrêté conjoint emploi/budget. Le 1er janvier 2015 est une origine historique de la revalorisation, non une date de réforme ou de revalorisation rétroactive nouvelle. Aucun pourcentage de modulation n'est inventé. Les V et VI de l'article 2 du décret 2021-1128 signalés par la note source restent à leur champ antérieur ; les règles de l'emploi pénitentiaire ne sont pas assimilées au contrat unique de droit privé.",
    removed=["Restriction des montants et modalités de l'aide au poste d'insertion aux seuls salariés recrutés sous contrat à durée déterminée."])

add('D5132-10-1', '''<p>Le présent article est abrogé à compter de l'entrée en vigueur de la loi portant cette abrogation.</p>
<p>À compter de cette date, l'organisation de périodes de mise en situation en milieu professionnel par l'entreprise d'insertion n'est plus subordonnée à leur prévision dans la convention mentionnée à l'article L. 5132-2, ni à l'inscription dans cette convention du nombre prévisionnel de salariés, des structures d'accueil, des modalités spécifiques d'accompagnement ou des objets de ces périodes. Aucun avenant, agrément ou dépôt de remplacement n'est exigé sur ce fondement.</p>
<p>Les périodes restent soumises aux articles L. 5135-1 à L. 5135-7, à leurs dispositions réglementaires d'application et à l'article D. 5132-10-2, notamment à la prescription, à l'accord de l'employeur et à la convention propre à chaque période. Les droits au statut, à l'indemnisation, au retour au poste, à la santé et à la sécurité demeurent applicables.</p>
<p>Les conventions et périodes valablement engagées avant cette date conservent leurs effets et les droits qui en résultent. Les clauses qui se bornent à reproduire l'exigence de prévision supprimée ne peuvent imposer une nouvelle formalité pour les périodes organisées après cette date ; les engagements autonomes d'accompagnement et les créances antérieures restent applicables. Les périodes sont accessibles aux salariés éligibles sous contrat unique à durée indéterminée comme aux titulaires d'anciens contrats, sans que leur durée mette fin à l'emploi.</p>''',
    "Abrogation prospective du cadrage supplémentaire de l'immersion dans la convention générale d'insertion et de ses quatre rubriques. Une prescription et une convention individuelle encadrent déjà chaque période : ces fondements autonomes assurent finalité, accord et protection du bénéficiaire. Aucune formalité équivalente ne remplace le dispositif abrogé ; les engagements d'accompagnement déjà valables et l'accès futur sont conservés.",
    "L5132-5, L5135-1/2/3/4/7, D5132-10-2/4 et D5135-3/4 lus. La convention individuelle et l'interdiction d'utiliser l'immersion pour un poste permanent, un surcroît temporaire, un emploi saisonnier ou un remplacement restent autonomes ; ni salaire ni statut ne sont supprimés. D5132-10-2 et les textes désignant la présente sous-section doivent être coordonnés pour ne pas rétablir le cadrage général. D5132-10-4, hors lot, garde sa transmission à l'ASP : elle n'est pas présentée comme abrogée. Les quatre rubriques retirées restent dans la source, sans être recopiées comme obligations.",
    repeal="Suppression de l'habilitation conventionnelle préalable spécifique aux immersions dans la convention générale d'insertion et de ses quatre mentions obligatoires, sans retrait de la convention individuelle ni des protections autonomes.")

add('D5132-10-3', '''<p>Le présent article est abrogé à compter de l'entrée en vigueur de la loi portant cette abrogation.</p>
<p>Le plafond fixant la durée cumulée des périodes de mise en situation en milieu professionnel à 25 % de la durée totale du contrat d'insertion cesse de s'appliquer aux périodes débutant à compter de cette date et à la fraction postérieure à cette date des périodes en cours. Aucun plafond calculé sur une durée présumée du contrat unique, de la mission, de l'aide ou du parcours ne lui est substitué.</p>
<p>Les limites et conditions propres à chaque période, notamment celles de l'article D. 5135-3, la prescription, la convention individuelle, l'accord de l'employeur, le statut et l'indemnisation du bénéficiaire, son droit au retour au poste et les règles de santé et de sécurité demeurent applicables. L'interdiction de pourvoir par ces périodes les emplois visés à l'article L. 5135-7 est maintenue.</p>
<p>Les périodes accomplies avant l'entrée en vigueur restent appréciées selon les règles alors applicables pour leurs effets antérieurs, sans remise en cause des droits acquis ni des créances correspondantes. Les conventions valablement conclues restent applicables, sous réserve de la suppression du plafond pour leur exécution future. La fin d'une période d'immersion ne met pas fin au contrat de travail.</p>''',
    "Abrogation effective du plafond global de 25 %, calculé sur un contrat à terme et inadapté au contrat unique. Il n'est remplacé ni par une durée fictive d'emploi ni par une autorisation. Les durées individuelles, le contrôle de finalité, la convention et la protection du bénéficiaire restent fondés sur le régime autonome des immersions.",
    "D5135-3 lu : maximum d'un mois de date à date pour la convention, renouvellement unique pour le même objet sous ses conditions, au plus deux conventions d'objets/objectifs différents dans la même structure sur douze mois et total de soixante jours, renouvellements compris. Ces limites ne sont pas abrogées. L5135-3/7 et D5132-10-2 lus pour statut, indemnisation, retour au poste et prohibition des emplois de substitution. Coordonner les renvois à la sous-section sans rétablir le ratio par un formulaire. Le projet distingue effets antérieurs et exécution future ; il n'annonce pas une suppression de toutes les règles des PMSMP.",
    repeal="Suppression pour l'exécution future du plafond global des immersions fixé à vingt-cinq pour cent de la durée du contrat d'insertion, avec maintien des limites individuelles et protections de droit commun.")

add('R5132-10-7', '''<p>La convention conclue avec une entreprise de travail temporaire d'insertion comporte :</p>
<p>1° Une présentation du projet d'insertion de la structure précisant :</p>
<p>a) Les caractéristiques générales de la structure ;</p>
<p>b) Les principales caractéristiques des personnes en difficulté embauchées ;</p>
<p>c) Les modalités d'accompagnement des salariés en insertion et de collaboration avec l'opérateur France Travail et avec les organismes chargés de leur insertion sociale et professionnelle. La structure peut faire état d'un label délivré par un tiers certificateur attestant de la qualité de son projet ; aucun label n'est exigé au titre du présent article ;</p>
<p>d) Abrogé ;</p>
<p>e) Abrogé ;</p>
<p>f) Les modalités de respect de la condition d'activité exclusive définie à l'article L. 5132-6, notamment l'affectation de l'intégralité des moyens humains et matériels à cette activité ;</p>
<p>g) Le cas échéant, le champ territorial d'intervention de l'entreprise lorsque celui-ci dépasse le ressort départemental ;</p>
<p>2° Les moyens en personnel, matériels et financiers mobilisés pour réaliser le projet d'insertion et accomplir les tâches administratives et obligations comptables résultant de l'activité de l'entreprise ;</p>
<p>3° Le nombre de postes d'insertion ouvrant droit à l'aide financière prévue à l'article R. 5132-10-12 ;</p>
<p>4° Les engagements d'insertion de la structure et les indicateurs rendant compte des actions et des résultats ;</p>
<p>5° Abrogé ;</p>
<p>6° La nature et le montant des autres aides publiques directes ou privées perçues les années antérieures, seulement lorsqu'elles financent les mêmes postes ou dépenses que la convention et que ces informations sont nécessaires au contrôle des règles de cumul applicables ;</p>
<p>7° Les modalités de suivi, de contrôle et d'évaluation de la convention.</p>
<p>Les informations et pièces exactes et à jour déjà légalement détenues par l'autorité de conventionnement sont réutilisées sans nouvelle production par la structure. La mention obligatoire de l'existence d'une autre convention, la justification de l'adéquation avec l'offre locale déjà existante et la fixation de modalités de dépôt des offres auprès de France Travail ne sont pas remplacées par une déclaration, une autorisation ou une certification équivalente. La collaboration prévue au c) et le contrôle de la réalité des actions d'insertion demeurent.</p>
<p>Ces simplifications s'appliquent dès l'entrée en vigueur de la loi les prévoyant aux conventions nouvelles et aux procédures en cours, sans nouveau dépôt ni reprise des délais. Les conventions déjà conclues restent valables ; leurs clauses qui imposent seulement les formalités supprimées cessent de les imposer pour l'avenir, sans affecter les engagements autonomes, les aides accordées ni les créances antérieures. Les emplois de droit privé conclus après l'entrée en vigueur du contrat unique sont à durée indéterminée ; la durée de la convention, de l'aide ou d'une mission ne met pas fin à ces emplois.</p>''',
    "Réforme de fond : retrait des mentions de convention déjà connue, de l'adéquation à l'offre locale et du circuit conventionnel obligatoire de dépôt des offres ; réduction de l'historique général des aides aux seules données antérieures nécessaires au contrôle des cumuls. Les pièces détenues ne sont plus redemandées. Accompagnement, collaboration avec France Travail, activité exclusive, moyens, postes aidés, résultats et contrôles sont maintenus. Le label reste une preuve facultative favorable, sans devenir une condition.",
    "L5132-6 et R5132-10-8/9/12/13/14 lus : activité exclusive et intégralité des moyens ont une base législative maintenue ; viabilité, comptes, suivi annuel autonome et contrôle d'exécution ne sont pas supprimés par cet article. R5132-10-14 prévient notamment le cumul d'aides d'État au même poste. Le projet ne supprime pas la connaissance des financements pertinents et ne crée pas une collecte de toutes les aides actuelles absente de la source. Les lettres d), e) et le 5° restent en place comme abrogés. L'adéquation locale retirée est la justification exigée par cet article ; aucune suppression implicite de critères législatifs ou européens d'aide n'est affirmée. Note historique : 1er juillet 2024, décret 2024-606. Les formulaires et clauses types doivent être coordonnés ; aucun achèvement de ces textes hors lot n'est déclaré.",
    removed=["Mention obligatoire de l'existence d'une autre convention au titre d'une structure d'insertion par l'activité économique.", "Justification conventionnelle obligatoire de l'adéquation du projet avec l'environnement local et l'offre d'insertion déjà existante.", "Obligation de fixer dans la convention les modalités de dépôt des offres d'emploi auprès de France Travail.", "Présentation indifférenciée des aides publiques ou privées des années antérieures sans lien nécessaire avec les règles de cumul de la convention.", "Nouvelle production des informations et pièces exactes et à jour déjà légalement détenues par l'autorité de conventionnement."])

add('R5132-10-12', '''<p>L'embauche, par une entreprise de travail temporaire d'insertion, d'une personne mentionnée à l'article L. 5132-1 sous contrat unique à durée indéterminée ouvre droit à une aide financière, dans la limite du nombre de postes d'insertion fixé par la convention. L'aide comprend un montant socle et un montant modulé. Le préfet détermine chaque année le montant modulé, dans les conditions prévues à l'article R. 5132-10-13, en tenant compte :</p>
<p>- des caractéristiques des personnes embauchées ;</p>
<p>- des actions et des moyens d'insertion mis en œuvre ;</p>
<p>- des résultats constatés à la sortie de la structure.</p>
<p>Cette éligibilité s'applique aux embauches de droit privé intervenant à compter de l'entrée en vigueur de la loi instituant le contrat unique. Les contrats de mission conclus avant cette date conservent les aides et les droits qui leur sont applicables ; ils ne peuvent être renouvelés après cette date en tant que contrats d'emploi à terme. La durée indéterminée du nouvel emploi ne peut, à elle seule, exclure l'aide ou en réduire le montant. Les conventions en cours demeurent utilisables sans nouveau conventionnement du seul fait de cette durée. La fin d'une mission, du parcours, de la convention ou de l'aide ne met pas fin à l'emploi.</p>
<p>L'aide particulière prévue à l'article R. 5132-10-13-1 demeure ouverte aux personnes qui remplissent ses conditions, y compris pour les situations futures. Lorsqu'un même poste et une même période sont éligibles aux deux dispositifs, l'entreprise peut demander le dispositif le plus favorable, sans cumul des deux aides pour ce poste et cette période. Les garanties propres à l'emploi intérimaire à durée indéterminée, notamment la garantie mensuelle et le décompte des intermissions, restent applicables.</p>''',
    "Réforme de fond : suppression de l'embauche sous contrat de mission à terme comme condition de l'aide ordinaire des entreprises de travail temporaire d'insertion. L'aide au socle et à la modulation est maintenue pour les futurs contrats uniques, avec trois critères et contingent de postes inchangés. L'aide particulière du CDI d'inclusion reste ouverte, avec choix favorable et sans double financement du même poste.",
    "L5132-6/6-1, L1251-58-1, R5132-10-13, R5132-10-13-1/2 et R5132-10-14 lus. Le contrat d'emploi est distinct de la mission commerciale ou d'affectation ; la limite de mission du régime particulier n'est pas transformée en terme d'emploi. L'aide d'inclusion garde ses paramètres propres, notamment 100 % du socle la première année et 70 % ensuite ; le choix exprès ne crée pas un cumul de ces montants avec le socle modulé. Coordonner les exclusions de section 4 bis dans L5132-6 et les arrêtés de versement pour la garantie et les intermissions, sans prétendre ces textes déjà réécrits. L'aide n'est pas due automatiquement pour toute la vie du CDI et aucune recette de financement n'est inventée.",
    removed=["Condition d'embauche par contrat de mission à terme pour accéder à l'aide financière ordinaire des entreprises de travail temporaire d'insertion."])

add('D5132-10-15', '''<p>Les personnes âgées d'au moins cinquante-sept ans qui rencontrent des difficultés sociales et professionnelles peuvent conclure avec une entreprise de travail temporaire d'insertion le contrat à durée indéterminée d'inclusion prévu à l'article L. 5132-6-1 dès le début de leur parcours d'insertion par l'activité économique.</p>
<p>Avant de conclure ce contrat, l'entreprise examine la situation de la personne au regard de l'emploi ainsi que les actions d'accompagnement et de formation déjà effectuées dans son parcours. Aucun contrat à durée déterminée préalable n'est exigé ; l'absence d'un tel contrat ou d'actions antérieures au début du parcours ne fait pas obstacle à cet examen ni à l'accès au contrat d'inclusion.</p>
<p>La suppression de l'attente minimale de douze mois et du préalable d'un CDD s'applique dès l'entrée en vigueur de la loi la prévoyant, y compris aux personnes dont le parcours a commencé avant cette date. Les contrats d'inclusion déjà conclus, leurs aides, les droits acquis et l'ancienneté sont préservés. Une conversion convenue conserve toute l'ancienneté et les créances acquises. Les garanties et les aides du régime d'inclusion restent ouvertes aux futures personnes éligibles. Les nouveaux emplois de droit privé relèvent du contrat unique à durée indéterminée ; ni la durée d'une mission ni celle de l'accompagnement ou de l'aide ne met fin à l'emploi. Les dispositions du présent article n'autorisent ni nouveau CDD ni renouvellement d'un ancien CDD après l'entrée en vigueur du contrat unique.</p>''',
    "Réforme de fond favorable : suppression effective des douze mois d'attente et du passage préalable par un CDD pour accéder au CDI d'inclusion. L'âge de cinquante-sept ans, les difficultés sociales et professionnelles et l'examen individuel sont conservés. L'accès devient possible dès le début du parcours, y compris pour les parcours en cours, sans fermer les aides ou garanties particulières aux futurs bénéficiaires.",
    "L5132-6-1 et R5132-10-13-1/2 lus : le dispositif d'inclusion, les aides et leur prorata gardent leurs conditions propres. La durée maximale de mission de trente-six mois de L5132-6-1 reste distincte de l'emploi à durée indéterminée ; aucun terme de CDI n'en résulte. L'examen reste assuré par l'entreprise, sans nouvel agrément, attestation ou demande à un prescripteur créée. La suppression des douze mois ne modifie pas l'âge de cinquante-sept ans et ne vaut pas rétroactivité générale des versements. Coordonner les formulaires, L5132-6 et le régime du CDI intérimaire sans ressusciter les CDD.",
    removed=["Délai minimal de douze mois après le début du parcours d'insertion avant de pouvoir conclure un CDI d'inclusion.", "Exigence d'un contrat à durée déterminée précédent comme préalable à l'examen et à l'accès au CDI d'inclusion."])

for number in ('D4154-3', 'R4451-58', 'R4451-100', 'R4523-1', 'R4543-22',
               'D4622-31', 'R4623-18', 'R4623-20', 'R4625-1'):
    drafts[number]['proposed_xml'] += "\n<p>Pour les contrats de droit public entrant dans le champ du présent article, les dispositions relatives aux contrats à durée déterminée demeurent applicables sans limitation tenant à la date d'entrée en vigueur du contrat unique de droit privé.</p>"
    drafts[number]['review_notes'] += " La réserve expresse des contrats publics ne leur étend pas le contrat unique et ne modifie pas le champ initial de l'article."

drafts['R4623-25-4']['review_notes'] += " R1234-4 et L1226-14/16/20 ont été lus : choix salarial le plus favorable, doublement et salaire propre des indemnités professionnelles sont conservés dans leurs champs respectifs ; leur absence de seuil n'est pas neutralisée."
drafts['R5132-10-7']['reason'] += " La liste des mentions exigées par cet article n'est plus ouverte par le mot 'notamment', sans supprimer les contrôles fondés sur d'autres textes."
drafts['R5132-10-7']['removed_provisions'].append("Caractère non limitatif des mentions conventionnelles exigibles sur le seul fondement du présent article.")

assert len(sources) == 24
assert len(drafts) == len(sources)
answer = []
for source in sources:
    item = {k: source[k] for k in ('code_id', 'source_id', 'source_sha256', 'number')}
    item.update(drafts[source['number']])
    assert not source.get('benefit_check_required') or len(item.get('benefit_review', '')) >= 100
    answer.append(item)
Path('answer.json').write_text(json.dumps(answer, ensure_ascii=False, indent=2) + '\n')
print(f'answer.json : {len(answer)} articles')
